from taf.config.wts import wts as Wts

from .exceptions import IdError
import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def expand_ranges(ranges):
    expanded = []
    for range_ in ranges.split(","):
        limits = list(map(int, range_.split("-")))
        expanded.extend(range(limits[0], limits[-1] + 1))
        if 0 in expanded:
            raise IdError("id 0 cannot be used")
    return expanded


class config(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    """
    This library provides higher-level operations on the WTS configuration files.
    Operations on basic.cfg file include: add one or multiple UE, gNB, supplementary cells for gNB/eNB, bearers.

    Example of Test cases and Keywords usage:

    .. code-block:: robotframework

        *** Settings ***
        Library     taf.wts.config

        *** Test Cases ***
        Edit Basic WTS config example

            Load Cfg    path/to/basic.cfg
            Add Ue      ue_id=1,3-5     ue_type=NSA      cell=2      ue_nr_capabilities=01000000010900
            Add Ue      ue_id=1-5       ue_type=SA      ue_nr_capabilities=01000000010900
            Add bearer  2       ue=1    qci=9   pdn=1   ip=4.7.254.208
            Add Cell    3,4     gnb=1    nr_arfcn=646000:646000
            Add gnb     2       ng=10.0.3.153     plmn=311:489
            Save Cfg    path/to/basic.cfg
    """
    def __init__(self, **kwargs):
        super(config, self).__init__(**kwargs)
        self._operation = Wts()

    def save_cfg(self, file_path):
        """
        Save all changes on specified basic.cfg file.

        :param str file_path: path.
        """
        self._operation.save_wts_cfg(file_path)

    def load_cfg(self, file_path):
        """
        Load basic.cfg file.
        Data will be stored in volatile memory.
        The keyword 'save_cfg` must be call to save changes on it.

        :param str file_path: path
        """
        self._operation.load_wts_cfg(file_path)

    def add_ue(self, ue_id, ue_type="NSA", change_pdn_ip=True, change_sec_key=False, **kwargs):
        """
        Insert a new UE(s) for SA or NSA.
        Make a copy of existing SA/NSA Ue in cfg file and insert new UE(s).

        :param str ue_id: single id or list/range of ids separated by ',' and '-'. (mandatory)
        :param str ue_type: type of UE 'SA' or 'NSA'. (mandatory)
        :param bool change_pdn_ip: if True ip will be incremented for each EU added. (optional)
        :param bool change_sec_key: if True sec_key will be incremented for each EU added. (optional)
        :param str kwargs: UE parameters to be modify or inserted. (optional)

        Example of test case:

        .. code-block:: robotframework

            *** Settings ***
            Library     taf.wts.config

            *** Test Cases ***
            TC
                Load Cfg    path/to/basic.cfg
                Add Ue      ue_id=2-4
                ...         ue_type=SA
                ...         change_sec_key=${True}
                ...         sec_key=01020304050607080A00
                ...         uec=2
                Save Cfg    path/to/basic.cfg
        """
        if ue_type.upper() == "SA":
            self._add_ue_sa(ue_id, change_pdn_ip, change_sec_key, kwargs)
        # elif ue_type.upper() == "SANSA":
        #    self.add_ue_sansa(ue_ids, change_pdn_ip, change_sec_key, kwargs)
        elif ue_type.upper() == "NSA":
            self._add_ue_nsa(ue_id, change_pdn_ip, change_sec_key, kwargs)

    #  def add_ue_sansa(self, ue_ids, change_pdn_ip, change_sec_key, kwargs):

    def _add_ue_sa(self, ue_ids, change_pdn_ip, change_sec_key, kwargs):
        """
        Insert a new UE(s) for SA.
        Make a copy of existing SA Ue in cfg file and insert new UE(s).

        :param str ue_ids: single id or list/range of ids separated by ',' and '-'. (mandatory)
        :param bool change_pdn_ip: if True ip (set_bearer command) will be incremented for each EU added. (optional)
        :param bool change_sec_key: if True sec_key will be incremented for each EU added. (optional)
        :param str kwargs: UE parameters to be modify or inserted. (optional)

        Example of test case:

        .. code-block:: robotframework

            *** Settings ***
            Library     taf.wts.config

            *** Test Cases ***
            TC
                Load Cfg    path/to/basic.cfg
                Add Ue      ue_id=2-4
                ...         ue_type=SA
                ...         change_sec_key=${True}
                ...         sec_key=01020304050607080A00
                ...         uec=2
                Save Cfg    path/to/basic.cfg

        basic.cfg :
            set_ue simulated id=1 uec=1 ptw=2.56 sec_key=01020304050607080FF0 imsi=250:555:21645400
            ue_param id=1 ue_nr_capabilities=A112C0EC100910400007F00
            set_pdu_gateway id=1 ue_nat_ip=72.23.0.11 dl_nat_gw=$SERVER_IP ul_nat_gw=$SERVER_IP
            ---> Add New SA UEs
            set_ue simulated id=2 uec=2 ptw=2.56 sec_key=01020304050607080A01 imsi=250:555:21645401
            ue_param id=2 ue_nr_capabilities=A112C0EC100910400007F00
            set_ue simulated id=3 uec=2 ptw=2.56 sec_key=01020304050607080A02 imsi=250:555:21645402
            ue_param id=3 ue_nr_capabilities=A112C0EC100910400007F00
            set_ue simulated id=4 uec=2 ptw=2.56 sec_key=01020304050607080A03 imsi=250:555:21645403
            ue_param id=4 ue_nr_capabilities=A112C0EC100910400007F00
            set_pdu_gateway id=2 ue_nat_ip=72.23.0.11 dl_nat_gw=$SERVER_IP ul_nat_gw=$SERVER_IP
            set_pdu_gateway id=3 ue_nat_ip=72.23.0.3 dl_nat_gw=$SERVER_IP ul_nat_gw=$SERVER_IP
            set_pdu_gateway id=4 ue_nat_ip=72.23.0.4 dl_nat_gw=$SERVER_IP ul_nat_gw=$SERVER_IP
        """
        expanded_ue_ids = expand_ranges(ue_ids)
        suci_value = self._operation.get_parameter("set_ue", "suci")
        base_ue_id = self._operation.get_parameter("set_ue suci={suci_value}".format(suci_value=suci_value), "id")
        previous_ue_id = base_ue_id
        for ue_id in expanded_ue_ids:
            is_present = self._operation.get("set_ue id={id}".format(id=ue_id))
            if is_present is None:
                self._operation.clone_and_modify(
                    command="set_ue id={base_ue_id}".format(base_ue_id=base_ue_id),
                    modification="id={ue_id}".format(ue_id=ue_id),
                    location="after",
                    reference="ue_param id={previous_ue_id}".format(previous_ue_id=previous_ue_id))
                self._operation.clone_and_modify(
                    command="ue_param id={base_ue_id}".format(base_ue_id=base_ue_id),
                    modification="id={ue_id}".format(ue_id=ue_id),
                    location="after",
                    reference="set_ue id={ue_id}".format(ue_id=ue_id))
                self._operation.clone_and_modify(
                    command="set_pdu_gateway id={base_ue_id}".format(base_ue_id=base_ue_id),
                    modification="id={ue_id}".format(ue_id=ue_id),
                    location="after",
                    reference="set_pdu_gateway id={previous_ue_id}".format(previous_ue_id=previous_ue_id))
                id_to_add = str(ue_id - 1)
                new_suci_value = suci_value[:-len(id_to_add)] + id_to_add
                kwargs['suci'] = new_suci_value
                self._modify_ue_params(ue_id, kwargs)
                self._increment_unique_params(ue_id, "SA", change_pdn_ip, change_sec_key)
                previous_ue_id = ue_id
                logger.info("command set_eu id='%s' added", ue_id)
            else:
                logger.info("command set_ue id='%s' is already present in the file", ue_id)

        # start to modify new slice command.
        # set_nwslice id=1 snssai=0x01:0xd143a5 amf=1 default=on ue=1-2
        is_present = self._operation.get("set_nwslice id=1")
        if is_present is None:
            logger.info("There is no set_nwslice command line, no need to change.")
        else:
            self._operation.modify(
                command="set_nwslice id=1",
                modification="{param}={value}".format(param="ue", value="all"))

    def _add_ue_nsa(self, ue_ids, change_pdn_ip, change_sec_key, kwargs):
        """
        Insert a new UE(s) for NSA.
        Make a copy of existing NSA Ue in cfg file and insert new UE(s).

        :param str ue_ids: single id or list/range of ids separated by ',' and '-'. (mandatory)
        :param bool change_pdn_ip: if True ip (set_bearer command) will be incremented for each EU added. (optional)
        :param bool change_sec_key: if True sec_key will be incremented for each EU added. (optional)
        :param str kwargs: UE parameters to be modify or inserted. (optional)

        Example of test case:

        .. code-block:: robotframework

            *** Settings ***
            Library     taf.wts.config

            *** Test Cases ***
            TC
                Load Cfg    path/to/basic.cfg
                Add Ue      ue_id=2-4
                ...         ue_type=NSA
                ...         change_sec_key=${True}
                ...         sec_key=01020304050607080A00
                ...         uec=2
                Save Cfg    path/to/basic.cfg

        basic.cfg :
            set_ue simulated id=1 uec=1 ptw=2.56 sec_key=01020304050607080FF0 imsi=250:555:21645400
            ue_param id=1 ue_eutra_nr_capabilities=A112C0EC100910400007F00
            set_bearer id=1 ue=1 pdn=1 ip=4.7.254.0
            ---> Add New NSA UEs
            set_ue simulated id=2 uec=2 ptw=2.56 sec_key=01020304050607080A01 imsi=250:555:21645401
            ue_param id=2 ue_eutra_nr_capabilities=A112C0EC100910400007F00
            set_ue simulated id=3 uec=2 ptw=2.56 sec_key=01020304050607080A02 imsi=250:555:21645402
            ue_param id=3 ue_eutra_nr_capabilities=A112C0EC100910400007F00
            set_ue simulated id=4 uec=2 ptw=2.56 sec_key=01020304050607080A03 imsi=250:555:21645403
            ue_param id=4 ue_eutra_nr_capabilities=A112C0EC100910400007F00
            set_bearer id=1 ue=2 pdn=1 ip=4.7.254.1
            set_bearer id=1 ue=3 pdn=1 ip=4.7.254.3
            set_bearer id=1 ue=4 pdn=1 ip=4.7.254.4
        """
        expanded_ue_ids = expand_ranges(ue_ids)
        imsi_value = self._operation.get_parameter("set_ue", "imsi")
        base_ue_id = self._operation.get_parameter("set_ue imsi={imsi_value}".format(imsi_value=imsi_value), "id")
        previous_ue_id = base_ue_id
        for ue_id in expanded_ue_ids:
            is_present = self._operation.get("set_ue id={id}".format(id=ue_id))
            if is_present is None:
                self._operation.clone_and_modify(
                    command="set_ue id={base_ue_id}".format(base_ue_id=base_ue_id),
                    modification="id={ue_id}".format(ue_id=ue_id),
                    location="after",
                    reference="ue_param id={previous_ue_id}".format(previous_ue_id=previous_ue_id))
                self._operation.clone_and_modify(
                    command="ue_param id={base_ue_id}".format(base_ue_id=base_ue_id),
                    modification="id={ue_id}".format(ue_id=ue_id),
                    location="after",
                    reference="set_ue id={ue_id}".format(ue_id=ue_id))
                self._operation.clone_and_modify(
                    command="set_bearer ue={base_ue_id}".format(base_ue_id=base_ue_id),
                    modification="ue={ue_id}".format(ue_id=ue_id),
                    location="after",
                    reference="set_bearer ue={previous_ue_id}".format(previous_ue_id=previous_ue_id))
                id_to_add = str(ue_id - 1)
                new_imsi_value = imsi_value[:-len(id_to_add)] + id_to_add
                kwargs['imsi'] = new_imsi_value
                self._modify_ue_params(ue_id, kwargs)
                self._increment_unique_params(ue_id, "NSA", change_pdn_ip, change_sec_key)
                previous_ue_id = ue_id
                logger.info("command set_eu id='%s' added", ue_id)
            else:
                logger.info("command set_ue id='%s' is already present in the file", ue_id)

    def _modify_ue_params(self, ue_id, parameters):
        ue_param_cmd = self._operation.get("ue_param id={id}".format(id=ue_id))
        for param_to_modify, value in parameters.items():
            if param_to_modify in ue_param_cmd:
                self._operation.modify(
                    command="ue_param id={id}".format(id=ue_id),
                    modification="{param}={value}".format(param=param_to_modify, value=value))
            else:
                self._operation.modify(
                    command="set_ue id={id}".format(id=ue_id),
                    modification="{param}={value}".format(param=param_to_modify, value=value))

    def _increment_unique_params(self, ue_id, ue_type, change_ip, change_sec_key):
        if change_sec_key:
            id_to_add = str(ue_id - 1)
            sec_key_value = self._operation.get_parameter("set_ue id={id}".format(id=ue_id), "sec_key")
            key_to_add = sec_key_value[:-len(id_to_add)] + id_to_add
            self._operation.modify(
                command="set_ue id={id}".format(id=ue_id),
                modification="sec_key={value}".format(value=key_to_add))
        if change_ip:
            id_to_add = str(ue_id)
            ip_value = ""
            if ue_type == "NSA":
                ip_value = self._operation.get_parameter("set_bearer ue={id}".format(id=ue_id), "ip")
                cmd = "set_bearer ue"
                param_to_modify = "ip"
            elif ue_type == "SA":
                ip_value = self._operation.get_parameter("set_pdu_gateway id={id}".format(id=ue_id), "ue_nat_ip")
                cmd = "set_pdu_gateway id"
                param_to_modify = "ue_nat_ip"
            if ip_value[0] == "$":  # if value of ip param is a variable e.g : $PDN_IP
                variable = ip_value[1:]
                value = self._operation.get_parameter("set", variable)
                ip_value = value.replace('"', '')
            ip_to_add = '.'.join(ip_value.split('.')[:-1] + [id_to_add])
            self._operation.modify(
                command="{cmd}={id}".format(cmd=cmd, id=ue_id),
                modification="{param_to_modify}={value}".format(param_to_modify=param_to_modify, value=ip_to_add))

    def add_cell(self, cell_id, node, *args):
        """
        Insert additional cells for gNB/eNB.
        Make a copy of existing cell for specific node and insert new cell for it with parameters

        :param str cell_id: single id or list/range of ids separated by ',' and '-'. (mandatory)
        :param str node: node and id associated with the cell e.g. enb=1(mandatory)
        :param str args: GNB parameters to be modify or inserted. (optional)

        Example of test case:

        .. code-block:: robotframework

            *** Settings ***
            Library     taf.wts.config

            *** Test Cases ***
            Add Cell in basic cfg
                    Add Cell    3,6
                    ...         gnb=1
                    ...         nr_arfcn=646000:646000
        """
        expanded_cell_ids = expand_ranges(cell_id)
        base_cell_id = self._operation.get_parameter("set_cell {node}".format(node=node), "id")
        previous_cell_id = base_cell_id
        for id in expanded_cell_ids:
            is_present = self._operation.get("set_cell id={id} {node}".format(id=id, node=node))
            if is_present is None:
                self._operation.clone_and_modify(
                    command="set_cell id={id} {node}".format(id=base_cell_id, node=node),
                    modification="id={id}".format(id=id),
                    location="after",
                    reference="set_cell id={id} {node}".format(id=previous_cell_id, node=node))
                for param_to_modify in args:
                    self._operation.modify(
                        command="set_cell id={id} {node}".format(id=id, node=node),
                        modification=param_to_modify)
                previous_cell_id = id
                logger.info("command set_cell id='%s' added", id)
            else:
                logger.info("command set_cell id='%s' for '%s' is already present in the file", id, node)

    def add_gnb(self, gnb_id, *args):
        """
        Add a new gNB(s).
        Make a copy of existing gNB in cfg file and insert new gNB(s) with parameters to be modified.

        :param str gnb_id: single id or list/range of ids separated by ',' and '-'. (mandatory)
        :param str args: GNB parameters to be modify or inserted. (optional)

        Example of test case:

        .. code-block:: robotframework

            *** Settings ***
            Library     taf.wts.config

            *** Test Cases ***
            Add GNB in basic cfg
                    Load Cfg    path/to/basic.cfg
                    Add gnb     2,3
                    ...         ng=10.0.3.153
                    ...         plmn=311:489
                    Save Cfg    path/to/basic.cfg

        basic.cfg :
            set_gnb id=1 type=external ng=10.0.1.111 daemon=$SERVER_IP:$EDAEMON_PORT
            ---> Add New GNB
            set_gnb id=2 type=external ng=10.0.3.153 daemon=$SERVER_IP:$EDAEMON_PORT plmn=311:489"
            set_gnb id=3 type=external ng=10.0.3.153 daemon=$SERVER_IP:$EDAEMON_PORT plmn=311:489"
        """
        expanded_gnb_ids = expand_ranges(gnb_id)
        base_gnb_id = self._operation.get_parameter("set_gnb", "id")
        previous_gnb_id = base_gnb_id
        for id in expanded_gnb_ids:
            is_present = self._operation.get("set_gnb id={id}".format(id=id))
            if is_present is None:
                self._operation.clone_and_modify(
                    command="set_gnb id={id}".format(id=base_gnb_id),
                    modification="id={id}".format(id=id),
                    location="after",
                    reference="set_gnb id={id}".format(id=previous_gnb_id))
                for param_to_modify in args:
                    self._operation.modify(
                        command="set_gnb id={id}".format(id=id),
                        modification=param_to_modify)
                previous_gnb_id = id
                logger.info("command set_gnb id='%s' added", id)
            else:
                logger.info("command set_gnb id='%s' is already present in the file", id)

    def add_bearer(self, bearer_id, ue_id, **kwargs):
        """
        Insert new bearer(s) for UE(s).

        :param str bearer_id: bearer id to be inserted (mandatory)
        :param stre ue_id: single ue id or list/range of ue ids to be associated (mandatory)
        :param str kwargs: bearer parameters to be modify or inserted. (optional)

        Example of test case:

        .. code-block:: robotframework

            *** Settings ***
            Library     taf.wts.config

            *** Test Cases ***
            Add bearer in basic cfg
                    Load Cfg    path/to/basic.cfg
                    Add bearer         bearer_id=2
                    ...                ue_ids=1
                    ...                ip=192.168.101.100
                    Save Cfg    path/to/basic.cfg

            basic.cfg :
                set_ue id=1 daemon=$SERVER_IP:$EDAEMON_PORT sec_key=0102030405060700C0D0EFF00 imsi=250:555:21645400
                ue_param id=1 ue_nr_capabilities=0123456789
                set_bearer id=1 ue=1 qci=9 pdn=1 ip=192.168.101.100 default=on trf_type=external priority=1
                ---> Add new bearer for UE 1
                set_bearer id=2 ue=1 qci=9 pdn=1 ip=192.168.101.100 default=on trf_type=external priority=1
        """
        expanded_ue_ids = expand_ranges(ue_id)
        for id in expanded_ue_ids:
            is_present = self._operation.get("set_bearer id={bearer_id} ue={ue_id}".format(
                bearer_id=bearer_id, ue_id=id))
            if is_present is None:
                self._operation.clone_and_modify(
                    command="set_bearer ue={ue_id}".format(ue_id=id),
                    modification="id={bearer_id}".format(bearer_id=bearer_id),
                    location="after",
                    reference="set_bearer ue={ue_id}".format(ue_id=id))
                for param_to_modify, value in kwargs.items():
                    self._operation.modify(
                        command="set_bearer id={bearer_id} ue={ue_id}".format(bearer_id=bearer_id, ue_id=id),
                        modification="{param}={value}".format(param=param_to_modify, value=value))
                logger.info("command set_bearer id={bearer_id} added for ue id={ue_id}".format(
                    bearer_id=bearer_id, ue_id=id))
            else:
                logger.info("command set_bearer id='%s' is already present in the file", bearer_id)
